INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Fix and Flip Series : Time Hacks', 'Dallas Real Estate Investors Group', 'Real Estate', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM,', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM, systems, automation, and AI to run flips more efficiently without letting every project take over your life. Fixing and flipping can become a full-time job fast. Contractors need answers. Materials need to be ordered. Draws need to be tracked. Budgets change. Inspections get scheduled. Properties need to be marketed. And somehow you are still supposed to find More info: https://www.meetup.com/meetup-group-dallasrealestateinvestorsgroup/events/316780704/', '2026-10-12T19:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Dallas Real Estate Investors Group', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/meetup-group-dallasrealestateinvestorsgroup/events/316780704/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Dallas Real Estate Investors Group', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/meetup-group-dallasrealestateinvestorsgroup/events/316694191/', '2026-10-14T09:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Dallas Real Estate Investors Group', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/meetup-group-dallasrealestateinvestorsgroup/events/316694191/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Dallas Real Estate Investors Group', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/meetup-group-dallasrealestateinvestorsgroup/events/316695062/', '2026-10-14T10:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Dallas Real Estate Investors Group', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/meetup-group-dallasrealestateinvestorsgroup/events/316695062/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate Agent Virtual Coffee Mastermind', 'Dallas Real Estate Investors Group', 'Real Estate', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every Thursday morning. It''s the perfect opportunity to build relationships with Realtors across the state and across the country (sometimes even on the other side of the world) that will serve your clients well when they need a referral. We have a short educational/informative presentation at the beginning of the meeting and then go into 3 or 4 person breakout More info: https://www.meetup.com/meetup-group-dallasrealestateinvestorsgroup/events/316709179/', '2026-10-15T09:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Dallas Real Estate Investors Group', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/meetup-group-dallasrealestateinvestorsgroup/events/316709179/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Free Live Webinar: 🤖 Build Your AI Workforce Before Your Competitors Do', 'Tampa AI Magnet Community', 'Founders & Startups', 'AI is changing the way businesses operate—but the real opportunity isn''t simply using more AI tools. It''s building an **AI workforce** that', 'AI is changing the way businesses operate—but the real opportunity isn''t simply using more AI tools. It''s building an **AI workforce** that can support your sales, marketing, customer service, and operations. In this free 60-minute on-demand workshop, AI strategist **[Michelle Hummel](https://www.michellehummel.com/)** will show you how to identify where AI can make the biggest impact in your business and which AI employees you should consider building first. You''ll discover how to: ⚡ Identify More info: https://www.meetup.com/meetup-group-tampa-social-media-enthusiasts/events/316696831/', '2026-10-14T13:00:00-04:00', 'Online event', 'Online event', 'Tampa', 'FL', '', 27.98, -82.34, 'Tampa AI Magnet Community', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/meetup-group-tampa-social-media-enthusiasts/events/316696831/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
