INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Stuck in Real Estate? 3 Reasons You Haven’t Closed a Deal', 'BPM REIA: Miami-Dade Real Estate Investors Association', 'Real Estate', 'You’ve been learning about real estate investing. So why does closing a deal still feel out of reach? Maybe you don’t know where to find', 'You’ve been learning about real estate investing. So why does closing a deal still feel out of reach? Maybe you don’t know where to find potential sellers. Maybe you’ve found properties but can’t tell which ones are worth pursuing. Or maybe you understand the basics, yet hesitate when it’s time to make a call or an offer. Join Anish Dave for a direct conversation about the three places aspiring investors commonly get stuck—and what it takes to start moving again. You’ll learn how to: * More info: https://www.meetup.com/miami-dade-real-estate-investors-association/events/316598523/', '2026-10-13T11:00:00-04:00', 'Online event', 'Online event', 'Miami', 'FL', '', 25.77, -80.29, 'BPM REIA: Miami-Dade Real Estate Investors Association', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/miami-dade-real-estate-investors-association/events/316598523/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
